**Agent class:**

```typescript
import { Agent, routeAgentRequest, callable } from "agents";

type Message = { role: "user" | "assistant"; content: string };
type State = { messages: Message[] };

export class ChatAgent extends Agent<Env, State> {
  initialState: State = { messages: [] };

  @callable()
  async sendMessage(text: string) {
    const messages = [...this.state.messages, { role: "user", content: text } as Message];
    this.setState({ messages }); // persisted automatically, survives restarts

    const reply = await this.generateReply(messages);
    this.setState({ messages: [...messages, { role: "assistant", content: reply }] });
    return reply;
  }

  @callable()
  async scheduleReminder(text: string) {
    const tomorrow = new Date(Date.now() + 24 * 60 * 60 * 1000);
    // durable, one-time schedule — fires even if the DO evicts in the meantime
    await this.schedule(tomorrow, "sendReminder", { text });
  }

  // Scheduled callback: name must match the string passed to schedule()
  async sendReminder(payload: { text: string }) {
    const messages = [
      ...this.state.messages,
      { role: "assistant", content: `Reminder: ${payload.text}` } as Message,
    ];
    this.setState({ messages });
    // push to a connected client, webhook, email, etc.
    this.broadcast(JSON.stringify({ type: "reminder", text: payload.text }));
  }

  private async generateReply(messages: Message[]) {
    // call your model of choice here
    return "...";
  }
}

export default {
  fetch: (req: Request, env: Env) =>
    routeAgentRequest(req, env) ?? new Response("Not found", { status: 404 }),
};
```

Key points:
- **State** — `this.setState()` writes to the DO's SQLite storage; `this.state` is reloaded automatically on the next request/session for that user (routed via `/agents/chat-agent/{userId}`), so history persists without extra plumbing.
- **Scheduling** — `this.schedule(tomorrow, "sendReminder", payload)` durably persists the task; the DO wakes itself at the target time and invokes the named method, even after eviction.
- One instance per user/conversation, addressed by a stable ID (e.g. `getAgentByName(env.ChatAgent, userId)`), keeps state and reminders scoped correctly.

