import { AIChatAgent } from "agents/ai-chat";
import { streamText, createUIMessageStream } from "ai";
import { openai } from "@ai-sdk/openai";

export class ChatAgent extends AIChatAgent<Env> {
  // Called by the SDK when it's time to run "task"
  async task(payload: { text: string }) {
    // Push a message into this same conversation's history
    await this.saveMessages([
      ...this.messages,
      { id: crypto.randomUUID(), role: "assistant",
        parts: [{ type: "text", text: payload.text }] },
    ]);
    // Optional: push to a connected client over the existing WebSocket
    this.broadcast(JSON.stringify({ type: "reminder", text: payload.text }));
  }

  async onChatMessage() {
    return createUIMessageStream({
      execute: async ({ writer }) => {
        // ... run the model, forward request.signal for cancellation ...
        const result = streamText({ model: openai("gpt-5"), messages: this.messages });

        // schedule a follow-up ~24h from now; survives DO eviction/restarts
        await this.schedule(60 * 60 * 24, "task", {
          text: "Following up on what we discussed — how did it go?",
        });

        writer.merge(result.toUIMessageStream());
      },
    });
  }
}

export default {
  fetch: (req: Request, env: Env) =>
    (await import("agents")).routeAgentRequest(req, env) ??
