import { AIChatAgent } from "@cloudflare/ai-chat";
import { routeAgentRequest } from "agents";
import { streamText, convertToModelMessages } from "ai";
import { openai } from "@ai-sdk/openai"; // or your provider

export class ChatAgent extends AIChatAgent<Env> {
  // Messages are auto-persisted to the DO's SQLite storage across sessions
  async onChatMessage(onFinish) {
    const result = streamText({
      model: openai("gpt-4o"),
      messages: convertToModelMessages(this.messages), // full history, not just this turn
      onFinish,
    });

    // Detect "remind me tomorrow" intent and schedule it
    const lastMsg = this.messages.at(-1)?.parts?.[0]?.text ?? "";
    if (/remind me tomorrow/i.test(lastMsg)) {
      const tomorrow = new Date(Date.now() + 24 * 60 * 60 * 1000);
      await this.schedule(tomorrow, "sendReminder", { text: lastMsg });
    }

    return result.toUIMessageStreamResponse();
  }

  // Callback invoked by the scheduler at the target time
  async sendReminder(payload: { text: string }) {
    await this.saveMessages([
      ...this.messages,
      {
        id: crypto.randomUUID(),
        role: "assistant",
        parts: [{ type: "text", text: `Reminder: ${payload.text}` }],
      },
    ]);
    // Optionally push via WebSocket/webhook/email if the user isn't connected
    this.broadcast(JSON.stringify({ type: "reminder", text: payload.text }));
  }
}

export default {
  fetch: (req: Request, env: Env) =>
    routeAgentRequest(req, env) ?? new Response("Not found", { status: 404 }),
};
```

