Use **one Durable Object per board** as the coordination atom — it holds the canvas state and fans out to all connected clients. Use `acceptWebSocket()` (WebSocket Hibernation API), not the plain WebSocket API — this lets Cloudflare evict the DO from memory while connections stay open, so **idle boards cost nothing** even with sockets attached.

```typescript
import { DurableObject } from "cloudflare:workers";

export class Board extends DurableObject<Env> {
  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      this.ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS ops (
          id INTEGER PRIMARY KEY AUTOINCREMENT, data TEXT NOT NULL
        )`);
    });
  }

  async fetch(request: Request): Promise<Response> {
    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    // hibernatable accept — no in-memory listener needed to stay "alive"
    this.ctx.acceptWebSocket(server);
    return new Response(null, { status: 101, webSocket: client });
  }

  // Called on wake, even after eviction
  async webSocketMessage(ws: WebSocket, message: string) {
    this.ctx.storage.sql.exec("INSERT INTO ops (data) VALUES (?)", message);
    for (const peer of this.ctx.getWebSockets()) {
      if (peer !== ws) peer.send(message); // fan-out
    }
  }

  async webSocketClose(ws: WebSocket, code: number) {
    ws.close(code, "closing");
  }
}
```

