export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const { email } = await request.json<{ email: string }>();

    const token = crypto.randomUUID();
    await env.RESET_TOKENS.put(token, email, { expirationTtl: 900 }); // 15 min

    const resetUrl = `https://yourdomain.com/reset-password?token=${token}`;

    const result = await env.EMAIL.send({
      from: { email: "no-reply@yourdomain.com", name: "Your App" },
      to: [{ email }],
      subject: "Reset your password",
      html: `<p>Click below to reset your password. This link expires in 15 minutes.</p>
             <p><a href="${resetUrl}">${resetUrl}</a></p>`,
      text: `Reset your password: ${resetUrl} (expires in 15 minutes)`,
    });

    return Response.json({ ok: result.success });
  },
};
```

**Key points:**
- The `from` address must use a domain already onboarded to Email Sending.
- Always include both `html` and `text` bodies — improves deliverability and client compatibility.
- Don't reveal whether the email exists in your system (send a generic "if that address exists, check your inbox" response) to avoid user enumeration.
- Use a short-lived, single-use token (KV with `expirationTtl` works well) rather than a long-lived or reusable one.
- No API keys needed — the binding handles auth via your Worker's Cloudflare account.

